         [ ["Get some rest tonight.","Bu akşam biraz dinlen."], ["Sleep well, okay?","İyi uyu, tamam mı?"] ],
         [ ["Message me tomorrow.","Yarın bana yaz."], ["Tell me if it is better.","Daha iyi olursa söyle."] ] ] },
  { f=>[ ["I will. Thank you for today, really. {phrase}","Yazarım. Bugün için gerçekten teşekkürler. {phrase}"],
