    o=>[ [ ["I have no idea.","Hiçbir fikrim yok."], ["I do not plan that far.","O kadar uzağı planlamam."] ],
         [ ["In another country, maybe.","Belki başka bir ülkede."], ["Living abroad, I hope.","Umarım yurt dışında."] ],
         [ ["Doing a job I love.","Sevdiğim bir işi yaparken."], ["Happier than now.","Şimdikinden mutlu."] ] ] },
  { f=>[ ["My plan is {dream}. I think about it a lot.","Benim planım {dream}. Bunu çok düşünüyorum."],
         ["For me the answer is simple: {dream}. I think about it more than I should.","Benim için cevap basit: {dream}. Gerekenden fazla düşünüyorum."] ],
    o=>[ [ ["That is a beautiful dream.","Bu güzel bir hayal."], ["I hope you do it.","Umarım yaparsın."] ],
         [ ["Is it possible?","Mümkün mü?"], ["What do you need first?","Önce neye ihtiyacın var?"] ],
         [ ["When will you start?","Ne zaman başlayacaksın?"], ["Do you have a plan?","Bir planın var mı?"] ] ] },
  { f=>[ ["I save money every month. Slowly.","Her ay para biriktiriyorum. Yavaş yavaş."],
         ["I put a little away every month. It is slow, but it is moving.","Her ay biraz kenara koyuyorum. Yavaş ama ilerliyor."] ],
    o=>[ [ ["That is smart.","Bu akıllıca."], ["Small steps work.","Küçük adımlar işe yarar."] ],
         [ ["Saving is hard for me.","Para biriktirmek bana zor geliyor."], ["I spend too much.","Çok harcıyorum."] ],
         [ ["How much do you save?","Ne kadar biriktiriyorsun?"], ["Do you have a target?","Bir hedefin var mı?"] ] ] },
  { f=>[ ["Do you want to live in another country?","Başka bir ülkede yaşamak ister misin?"],
         ["Would you ever move abroad permanently, or is that too big a step?","Hiç temelli yurt dışına taşınır mıydın, yoksa çok mu büyük bir adım?"] ],
    o=>[ [ ["Yes, I think about it.","Evet, düşünüyorum."], ["That is my dream too.","Benim de hayalim bu."] ],
         [ ["No, I love my country.","Hayır, ülkemi seviyorum."], ["My family is here.","Ailem burada."] ],
         [ ["Maybe for a few years.","Belki birkaç yıllığına."], ["To work, not forever.","Çalışmak için, temelli değil."] ] ] },
  { f=>[ ["Which country? Tell me.","Hangi ülke? Söyle bakalım."],
         ["Which country would it be? Everyone has one in their head.","Hangi ülke olurdu? Herkesin kafasında bir tane var."] ],
    o=>[ [ ["England, maybe.","Belki İngiltere."], ["Somewhere in Europe.","Avrupa'da bir yer."] ],
         [ ["Canada or Australia.","Kanada ya da Avustralya."], ["Somewhere with nature.","Doğası olan bir yer."] ],
         [ ["I would visit {city} first!","Önce {city} gelirdim!"], ["Your city, of course!","Tabii ki senin şehrin!"] ] ] },
  { f=>[ ["Then you must come and stay with me!","O zaman gelip bende kalmalısın!"],
         ["Then it is decided. When you come, you stay with me, no arguments.","O zaman karar verildi. Geldiğinde bende kalıyorsun, tartışma yok."] ],
    o=>[ [ ["Really? Thank you!","Gerçekten mi? Teşekkürler!"], ["I would love that!","Buna bayılırım!"] ],
         [ ["I do not want to be a problem.","Sorun olmak istemem."], ["Are you sure?","Emin misin?"] ],
         [ ["Then you come to Turkey!","O zaman sen de Türkiye'ye gel!"], ["My home is yours too.","Benim evim de senin."] ] ] },
  { f=>[ ["I would love to see Turkey. Really.","Türkiye'yi görmeyi çok isterim. Cidden."],
         ["I have wanted to visit Turkey for years. The food alone would be worth it.","Yıllardır Türkiye'yi görmek istiyorum. Sadece yemekler bile buna değer."] ],
    o=>[ [ ["I will show you everything!","Sana her şeyi göstereceğim!"], ["You will love it.","Bayılacaksın."] ],
         [ ["Which city do you want to see?","Hangi şehri görmek istersin?"], ["Istanbul or the coast?","İstanbul mu sahil mi?"] ],
         [ ["Come in spring, it is perfect.","İlkbaharda gel, mükemmel olur."], ["Not in summer, too hot!","Yazın değil, çok sıcak!"] ] ] },
  { f=>[ ["It is nice to make plans. Even small ones.","Plan yapmak güzel. Küçük olsa bile."],
         ["Making plans is important, even the ones that never happen. They keep you going.","Plan yapmak önemli, hiç gerçekleşmeyenler bile. İnsanı ayakta tutuyor."] ],
    o=>[ [ ["I agree.","Katılıyorum."], ["Plans give hope.","Planlar umut veriyor."] ],
         [ ["I never plan anything!","Ben hiç plan yapmam!"], ["I live day by day.","Günü gününe yaşarım."] ],
         [ ["Let us make a real plan.","Gerçek bir plan yapalım."], ["Give me a date!","Bana bir tarih ver!"] ] ] },
  { f=>[ ["Next summer. Let us say next summer.","Gelecek yaz. Gelecek yaz diyelim."],
         ["Next summer, then. Let us say it out loud so it becomes real.","O zaman gelecek yaz. Yüksek sesle söyleyelim ki gerçek olsun."] ],
    o=>[ [ ["Next summer! Deal.","Gelecek yaz! Anlaştık."], ["It is a promise.","Söz olsun."] ],
         [ ["I will start saving.","Para biriktirmeye başlayacağım."], ["I need to save money.","Para biriktirmem lazım."] ],
         [ ["Do not forget this talk!","Bu konuşmayı unutma!"], ["I will remind you!","Sana hatırlatacağım!"] ] ] },
  { f=>[ ["I will not forget. Thank you for the dream. {phrase}","Unutmayacağım. Hayal için teşekkürler. {phrase}"],
         ["I will not forget this conversation. Thank you for the dream, honestly. {phrase}","Bu konuşmayı unutmayacağım. Hayal için cidden teşekkürler. {phrase}"] ],
    o=>[ [ ["See you next summer!","Gelecek yaz görüşürüz!"], ["It is going to happen.","Bu olacak."] ],
         [ ["Thank you for today, {name}.","Bugün için teşekkürler {name}."], ["I enjoyed this talk.","Bu sohbetten keyif aldım."] ],
         [ ["Talk to me again tomorrow.","Yarın yine konuş benimle."], ["Same time next week?","Haftaya aynı saatte?"] ] ] }
 ]
